    private void startSheet(String sheetId) {
        List<String> sets = columns("SHEET").stream().filter(c -> !SHEET_KEPT.contains(c.name()))
                .filter(c -> c.defaulted() || c.nullable())
                .map(c -> c.name() + (c.defaulted() ? " = DEFAULT" : " = NULL")).toList();
